// The tool catalogue. One entry per operation the add-in implements, in one place, because three
// things read it and they must not drift apart: the MCP server (registration and schemas), the tests
// (catalogue invariants), and the README's tool table (generated by `npm run tools:table`).
//
// `write: true` means the tool changes the model. Those are refused unless the operator turned
// writes on for BOTH processes (server --allow-writes and the add-in), and every one of them takes
// `apply: false` by default so the first answer is a preview, not a change. See docs/security.md.
//
// `op` is the bridge operation (docs/protocol.md). The server never talks Revit API directly: it
// forwards { op, args } to the add-in, which does the Revit work on Revit's own thread.
import { z } from 'zod';
import { PRESETS, MOODS } from './camera.mjs';

const elementId = z.number().int().positive().describe('Revit element id, as returned by query_elements');
const limit = z.number().int().min(1).max(500).optional().describe('Maximum rows to return (default 50, max 500)');

